		Map.entry(InterfaceID.MagicSpellbook.HUNTER_KIT, hunterKit(ItemID.DREAM_HUNTER_BOX, HUNTER_TOOLS)),
		Map.entry(InterfaceID.MagicSpellbook.DEGRIME, anyOf(GRIMY_HERBS)),
